    return n*n - n + 1

for n in range(20):
    print(f"g({n}) = {g(n)}, Parity: {g(n) % 2}")

M = 100
N = 0

for x in range(M):
    for y in range(M):
        S = x + y

        # Parity rules for f(x, y) = T_S + y
        # T_S parity repeats every 4: (E, O, O, E) for S mod 4 = (0, 1, 2, 3)

        S_mod_4 = S % 4
        y_is_odd = y % 2 != 0
        y_is_even = y % 2 == 0

        is_odd = False

        if S_mod_4 == 0: # T_S is Even (0)
            # Need 0 + y = Odd => y must be Odd
            if y_is_odd:
                is_odd = True
        elif S_mod_4 == 1: # T_S is Odd (1)
            # Need 1 + y = Odd => y must be Even
            if y_is_even:
                is_odd = True
        elif S_mod_4 == 2: # T_S is Odd (1)
            # Need 1 + y = Odd => y must be Even
            if y_is_even:
                is_odd = True
        elif S_mod_4 == 3: # T_S is Even (0)
            # Need 0 + y = Odd => y must be Odd
            if y_is_odd:
                is_odd = True

        if is_odd:
            N += 1

print(N)

def f(x, y):
    # f(x, y) = T_{x+y} + y
    S = x + y
    T_S = S * (S + 1) // 2
    return T_S + y

