def f(x, y):
    # f(x, y) = ( (x+y)(x+y+1)/2 + y )
    s = x + y
    triangular_number = s * (s + 1) // 2
    return triangular_number + y

N = 0
limit = 100

for x in range(limit):
    for y in range(limit):
        value = f(x, y)
        if value % 2 != 0:
            N += 1

